<?php require_once __DIR__.'/../lib/auth.php';require_admin();$year=(int)($_GET['year']??date('Y'));$s=db()->prepare("SELECT e.employee_no,e.name,e.position,d.name department_name,c.* FROM leave_allowance_calculations c JOIN employees e ON e.id=c.employee_id LEFT JOIN departments d ON d.id=e.department_id WHERE c.calc_year=? ORDER BY e.sort_order,e.id");$s->execute([$year]);header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition:attachment; filename=leave_allowance_'.$year.'.csv');echo "\xEF\xBB\xBF";$o=fopen('php://output','w');fputcsv($o,['사번','성명','직책','부서','기준연도','월통상임금','부여일수','사용일수','제외일수','조정일수','지급일수','1일통상임금','연차수당','확정']);foreach($s as $r)fputcsv($o,[$r['employee_no'],$r['name'],$r['position'],$r['department_name'],$year,$r['monthly_ordinary_wage'],$r['granted_days'],$r['used_days'],$r['excluded_days'],$r['adjustment_days'],$r['payable_unused_days'],$r['daily_wage'],$r['allowance_amount'],$r['is_confirmed']?'확정':'미확정']);fclose($o);
